import { useEffect, useMemo, useState } from 'react'
import { ChevronLeft, ChevronRight, LoaderCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { CardContent } from '@/components/ui/card'
import type { AiringSchedule } from '@/lib/recording'

interface ChannelDetails {
  callSign: string
  name: string
  major: number
  minor: number
  network: string
}

export interface GridChannelInfo {
  objectId: number
  channel: ChannelDetails
}

interface EpisodeInfo {
  title: string | null
  description: string
  number: number
  seasonNumber: number
}

interface MovieAiringInfo {
  releaseYear: number
}

interface GridAiring {
  path: string
  airingDetails: {
    datetime: string
    duration: number
    showTitle: string
  }
  moviePath?: string | null
  seriesPath?: string | null
  episode?: EpisodeInfo | null
  movieAiring?: MovieAiringInfo | null
  schedule?: AiringSchedule | null
}

interface GridChannel {
  channel: GridChannelInfo
  airings: GridAiring[]
}

interface GuideGridResponse {
  updatedAt: string | null
  channels: GridChannel[]
}

export interface SelectedProgram {
  title: string
  subtitle: string
  description: string | null
  backgroundImageUrl: string | null
  thumbnailImageUrl: string | null
  // Set when the selection is an actual airing (not just a channel with nothing on) -
  // lets the preview pane offer to record it.
  path: string | null
  schedule: AiringSchedule | null
  // Set when the airing is a movie - lets the preview pane fetch its full details
  // (cast/directors/runtime) from GET /api/movies/{id}.
  moviePath: string | null
}

export interface WatchedChannel {
  objectId: number
  tuningLabel: string
  channelLabel: string
}

function channelLabelFor(c: GridChannel): string {
  const { major, minor, callSign } = c.channel.channel
  const parts: string[] = []
  if (major != null && minor != null) {
    parts.push(`${major}.${minor}`)
  }
  if (callSign) parts.push(callSign)
  return parts.join(' ')
}

function airingKey(a: GridAiring): string {
  // The Tablo guide occasionally lists two distinct airings on the same channel with an
  // identical start time and title (e.g. back-to-back re-airs) - `path` is unique per
  // airing object, so prefer it over datetime+title to avoid colliding React keys.
  return a.path || a.airingDetails.datetime + a.airingDetails.showTitle
}

function nowPlayingAiring(airings: GridAiring[]): GridAiring | null {
  const now = Date.now()
  return (
    airings.find((a) => {
      const start = new Date(a.airingDetails.datetime).getTime()
      const end = start + a.airingDetails.duration * 1000
      return start <= now && now < end
    }) ?? null
  )
}

function selectionForChannel(c: GridChannel, noListings: boolean): SelectedProgram {
  const nowPlaying = nowPlayingAiring(c.airings)
  if (nowPlaying) {
    return {
      title: nowPlaying.airingDetails.showTitle,
      subtitle: describeAiring(nowPlaying, c.channel.channel.callSign),
      description: descriptionFor(nowPlaying),
      backgroundImageUrl: backgroundImageUrlFor(nowPlaying),
      thumbnailImageUrl: thumbnailImageUrlFor(nowPlaying),
      path: nowPlaying.path,
      schedule: nowPlaying.schedule ?? null,
      moviePath: nowPlaying.moviePath ?? null,
    }
  }

  const { major, minor, network } = c.channel.channel
  return {
    title: c.channel.channel.callSign,
    // With no listings at all (an expired or empty guide), the channel is all there is to show.
    subtitle: [`${major}.${minor}`, network, noListings && 'No listings available']
      .filter(Boolean)
      .join(' · '),
    description: null,
    backgroundImageUrl: null,
    thumbnailImageUrl: null,
    path: null,
    schedule: null,
    moviePath: null,
  }
}

// e.g. "3.2 Me-TV M*A*S*H" - what the player shows while it tunes.
function tuningLabelFor(c: GridChannel): string {
  const { major, minor, callSign } = c.channel.channel
  const nowPlaying = nowPlayingAiring(c.airings)
  return [`${major}.${minor}`, callSign, nowPlaying?.airingDetails.showTitle].filter(Boolean).join(' ')
}

function artworkUrlFor(kind: 'background' | 'thumbnail', a: GridAiring): string | null {
  if (a.moviePath) return `/api/images/${kind}?moviePath=${encodeURIComponent(a.moviePath)}`
  if (a.seriesPath) return `/api/images/${kind}?seriesPath=${encodeURIComponent(a.seriesPath)}`
  return null
}

function backgroundImageUrlFor(a: GridAiring): string | null {
  return artworkUrlFor('background', a)
}

// The series/movie poster (portrait, usually with the title on it).
function thumbnailImageUrlFor(a: GridAiring): string | null {
  return artworkUrlFor('thumbnail', a)
}

function describeAiring(a: GridAiring, channelName: string): string {
  if (a.episode) {
    const se = a.episode.seasonNumber > 0 ? `S${a.episode.seasonNumber}E${a.episode.number}` : null
    const parts = [se, a.episode.title].filter(Boolean)
    if (parts.length > 0) return parts.join(' · ')
  }

  if (a.movieAiring) {
    return a.movieAiring.releaseYear ? `Movie · ${a.movieAiring.releaseYear}` : 'Movie'
  }

  const start = new Date(a.airingDetails.datetime)
  return `${channelName} · ${start.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}`
}

function descriptionFor(a: GridAiring): string | null {
  return a.episode?.description || null
}

const WINDOW_HOURS = 6
const HOUR_WIDTH_PX = 240
const HALF_HOUR_WIDTH_PX = HOUR_WIDTH_PX / 2
const ROW_HEIGHT_PX = 56
const WINDOW_MS = WINDOW_HOURS * 60 * 60 * 1000

// The backend only rebuilds its airings cache every 15 minutes (AiringsRefreshService),
// but polling this endpoint is cheap - it just reads that in-memory cache, no device call -
// so poll more often to pick up a fresh cache soon after it lands rather than waiting a
// full cycle.
const POLL_INTERVAL_MS = 60_000
// Until the server's first airings refresh lands, check back often so listings appear promptly.
const LOADING_POLL_INTERVAL_MS = 5_000

function formatUpdatedAt(updatedAt: string, now: number): string {
  const seconds = Math.max(0, Math.round((now - new Date(updatedAt).getTime()) / 1000))
  if (seconds < 60) return 'just now'
  const minutes = Math.round(seconds / 60)
  return `${minutes}m ago`
}

function roundDownToHalfHour(date: Date): Date {
  const rounded = new Date(date)
  rounded.setMinutes(date.getMinutes() < 30 ? 0 : 30, 0, 0)
  return rounded
}

// The current time, updated on every minute - and straight away when the page comes back into
// view, since background tabs (and sleeping machines) hold timers back.
function useMinuteClock(): number {
  const [now, setNow] = useState(() => Date.now())

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>
    function tick() {
      setNow(Date.now())
      timer = setTimeout(tick, 60_000 - (Date.now() % 60_000))
    }
    function onVisibilityChange() {
      if (document.visibilityState !== 'visible') return
      clearTimeout(timer)
      tick()
    }

    timer = setTimeout(tick, 60_000 - (Date.now() % 60_000))
    document.addEventListener('visibilitychange', onVisibilityChange)
    return () => {
      clearTimeout(timer)
      document.removeEventListener('visibilitychange', onVisibilityChange)
    }
  }, [])

  return now
}

function formatTick(date: Date): string {
  return date.toLocaleTimeString([], {
    hour: 'numeric',
    minute: date.getMinutes() === 0 ? undefined : '2-digit',
  })
}

// One row per channel on the device (its own channel list, never the guide's airings), with
// whatever airings the guide has for it - so every channel shows, and can be tuned, while the
// guide is loading or has no listings. No rows until that list has loaded.
function gridRows(channels: GridChannelInfo[] | undefined, data: GuideGridResponse | null): GridChannel[] {
  const airingsById = new Map((data?.updatedAt ? data.channels : []).map((c) => [c.channel.objectId, c.airings]))
  return (channels ?? []).map((channel) => ({ channel, airings: airingsById.get(channel.objectId) ?? [] }))
}

interface GuideGridProps {
  // Fired for both channel and program clicks - updates the preview pane's details.
  onSelect?: (program: SelectedProgram) => void
  // Fired only for channel-column clicks: program cells just preview what's on, without
  // interrupting the channel already playing.
  onWatchChannel?: (channel: WatchedChannel) => void
  // Channel object id -> the tuner last known to be showing it, shown on that channel's row.
  tunerByChannel?: Record<number, number>
  // The device's channel list, loaded independently of airings - the grid's rows.
  channels?: GridChannelInfo[]
}

export function GuideGrid({ onSelect, onWatchChannel, tunerByChannel, channels }: GuideGridProps) {
  const now = useMinuteClock()
  // The window paged to with the arrows; null follows the clock, moving on every half hour.
  const [pinnedStart, setPinnedStart] = useState<number | null>(null)
  const currentStart = roundDownToHalfHour(new Date(now)).getTime()
  const windowStartMs = pinnedStart ?? currentStart
  const [data, setData] = useState<GuideGridResponse | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [selectedKey, setSelectedKey] = useState<string | null>(null)
  const [selectedChannelId, setSelectedChannelId] = useState<number | null>(null)

  const windowStart = useMemo(() => new Date(windowStartMs), [windowStartMs])
  const windowEnd = useMemo(() => new Date(windowStartMs + WINDOW_MS), [windowStartMs])

  // Paging back to the current window goes back to following the clock.
  function pageBy(windows: number) {
    const start = windowStartMs + windows * WINDOW_MS
    setPinnedStart(start === currentStart ? null : start)
  }

  useEffect(() => {
    let cancelled = false
    let timer: ReturnType<typeof setTimeout> | undefined

    function load() {
      const params = new URLSearchParams({
        from: windowStart.toISOString(),
        to: windowEnd.toISOString(),
      })

      fetch(`/api/guide/grid?${params}`)
        .then((res) => {
          if (!res.ok) throw new Error(`API returned ${res.status}`)
          return res.json() as Promise<GuideGridResponse>
        })
        .then((d) => {
          if (cancelled) return
          setData(d)
          setError(null)
          return d
        })
        .catch((err) => {
          if (!cancelled) setError(err.message)
        })
        .then((d) => {
          if (!cancelled) timer = setTimeout(load, d?.updatedAt ? POLL_INTERVAL_MS : LOADING_POLL_INTERVAL_MS)
        })
    }

    load()

    return () => {
      cancelled = true
      clearTimeout(timer)
    }
  }, [windowStart, windowEnd])

  const ticks = useMemo(() => {
    const result: Date[] = []
    for (let t = windowStart.getTime(); t < windowEnd.getTime(); t += 30 * 60 * 1000) {
      result.push(new Date(t))
    }
    return result
  }, [windowStart, windowEnd])

  const nowOffset =
    now < windowStartMs || now > windowEnd.getTime()
      ? null
      : ((now - windowStartMs) / WINDOW_MS) * (WINDOW_HOURS * HOUR_WIDTH_PX)

  function positionOf(airing: GridAiring) {
    const start = new Date(airing.airingDetails.datetime).getTime()
    const end = start + airing.airingDetails.duration * 1000
    const clippedStart = Math.max(start, windowStart.getTime())
    const clippedEnd = Math.min(end, windowEnd.getTime())
    const totalWidth = WINDOW_HOURS * HOUR_WIDTH_PX

    return {
      left: ((clippedStart - windowStart.getTime()) / WINDOW_MS) * totalWidth,
      width: Math.max(((clippedEnd - clippedStart) / WINDOW_MS) * totalWidth - 4, 20),
    }
  }

  const listingsLoading = !data?.updatedAt
  // The server's grid only has channels with airings, so it's empty when the guide is.
  const noListings = !listingsLoading && data.channels.length === 0
  const rows = useMemo(() => gridRows(channels, data), [channels, data])

  return (
    <>
      <div className="flex items-center justify-between border-b px-4 py-2">
        <div className="flex items-baseline gap-2">
          <span className="text-sm font-medium">
            {windowStart.toLocaleString([], { weekday: 'short', hour: 'numeric', minute: '2-digit' })} &ndash;{' '}
            {windowEnd.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}
          </span>
          {data?.updatedAt ? (
            <span className="text-muted-foreground text-xs">
              {noListings ? 'No TV listings available' : `Updated ${formatUpdatedAt(data.updatedAt, now)}`}
            </span>
          ) : (
            <span className="text-muted-foreground flex items-center gap-1 self-center text-xs">
              <LoaderCircle className="size-3 animate-spin" aria-hidden />
              Loading listings…
            </span>
          )}
        </div>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => pageBy(-1)}
          >
            <ChevronLeft className="size-4" />
          </Button>
          <Button variant="outline" size="sm" onClick={() => setPinnedStart(null)}>
            Now
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={() => pageBy(1)}
          >
            <ChevronRight className="size-4" />
          </Button>
        </div>
      </div>

      {error && (
        <div className="text-destructive p-4 text-sm">Couldn't load the guide: {error}</div>
      )}

      <CardContent className="flex-1 overflow-auto p-0">
        <div className="flex w-fit">
          <div className="bg-card sticky left-0 z-10 w-32 shrink-0 border-r">
            <div className="h-8 border-b" />
            {rows.map((c) => (
              <button
                key={c.channel.objectId}
                type="button"
                className={
                  'flex w-full flex-col justify-center gap-0.5 border-b px-2 text-left text-sm transition-colors ' +
                  (c.channel.objectId === selectedChannelId ? 'bg-secondary' : 'hover:bg-muted')
                }
                style={{ height: ROW_HEIGHT_PX }}
                onClick={() => {
                  setSelectedChannelId(c.channel.objectId)
                  setSelectedKey(null)
                  onSelect?.(selectionForChannel(c, noListings))
                  onWatchChannel?.({
                    objectId: c.channel.objectId,
                    tuningLabel: tuningLabelFor(c),
                    channelLabel: channelLabelFor(c),
                  })
                }}
              >
                <div className="flex items-center gap-2">
                  <span className="text-muted-foreground text-xs">
                    {c.channel.channel.major}.{c.channel.channel.minor}
                  </span>
                  <span className="truncate font-medium">{c.channel.channel.callSign}</span>
                </div>
                <div className="text-muted-foreground flex items-center justify-between gap-2 text-xs">
                  <span className="truncate">{c.channel.channel.network}</span>
                  {tunerByChannel?.[c.channel.objectId] !== undefined && (
                    <span className="shrink-0">Tuner {tunerByChannel[c.channel.objectId]}</span>
                  )}
                </div>
              </button>
            ))}
          </div>

          <div className="relative" style={{ width: WINDOW_HOURS * HOUR_WIDTH_PX }}>
            <div className="flex h-8 border-b">
              {ticks.map((tick) => (
                <div
                  key={tick.toISOString()}
