                      {a.airingDetails.showTitle}
                    </button>
                  )
                })}
              </div>
            ))}

            {nowOffset !== null && (
              <div className="bg-primary absolute top-0 bottom-0 w-px" style={{ left: nowOffset }} />
            )}
          </div>
        </div>
      </CardContent>
